(function(){"use strict";const SCREEN_DATA=[{title:"Login Screen to Omni Space",desc:"Apps login screen and a command center for all occult sciences — enter and explore.",},{title:"Daily Horoscope",desc:"Precise daily,weekly and monthly readings powered by real planetary positions.",},{title:"Kundli&Birth Chart",desc:"Your complete Vedic birth chart with dashas,yogas and deep planetary insight.",},{title:"Numerology",desc:"Life path,destiny number,name and mobile numerology explained in detail.",},{title:"Palmistry",desc:"Detailed palm reading guides for lines,mounts and beyond.",},{title:"Tarot&Oracle",desc:"Daily card pulls and rich,guided spreads for intuitive clarity.",},{title:"Vastu Guidance",desc:"Harmonise your home and workspace with practical Vastu remedies.",},{title:"Vedic Calendar",desc:"Everything from Pachanga to tithis to planetary events at your fingertips.",},{title:"Join us as an expert",desc:"If you feel you have the occult knowledge to share with the world,then join us.",},{title:"Community connect",desc:"Connect with like minded and spiritualy aligned people.",},{title:"Ohm Score breakdown",desc:"Identify what's stopping you from outperforming.",},{title:"Remedies&Rituals",desc:"Gentle remedies,mantras and rituals tailored to your planetary profile.",},{title:"Your Sacred Space",desc:"Your account details,orders,wallet,terms,policies,offers etc..",},];const marqueeTrack=document.getElementById("marqueeTrack");const marqueeStage=document.getElementById("marqueeStage");const captionTitle=document.getElementById("captionTitle");const captionDesc=document.getElementById("captionDesc");const captionBox=document.getElementById("captionBox");let activeIndex=0;let isPaused=false;function buildPhones(){if(!marqueeTrack)return;const fragment=document.createDocumentFragment();for(let i=0;i<SCREEN_DATA.length;i++){const num=i+1;const phone=document.createElement("div");phone.className="phone"+(i===0?" active":"");phone.dataset.index=i;phone.setAttribute("role","button");phone.setAttribute("tabindex","0");phone.setAttribute("aria-label","Screenshot "+num+":"+SCREEN_DATA[i].title);const frame=document.createElement("div");frame.className="phone-frame";const notch=document.createElement("div");notch.className="phone-notch";const screen=document.createElement("div");screen.className="phone-screen";const img=document.createElement("img");img.src="assets/screenshots/"+num+"-trim.png";img.alt="GreatOhm app screenshot "+num;img.loading="lazy";img.draggable=false;screen.appendChild(img);const shadow=document.createElement("div");shadow.className="phone-shadow";frame.appendChild(notch);frame.appendChild(screen);phone.appendChild(frame);phone.appendChild(shadow);fragment.appendChild(phone);}marqueeTrack.appendChild(fragment);const firstSet=Array.prototype.slice.call(marqueeTrack.children);firstSet.forEach(function(original){marqueeTrack.appendChild(original.cloneNode(true));});const allPhones=marqueeTrack.children;for(let j=0;j<allPhones.length;j++){const idx=j % SCREEN_DATA.length;allPhones[j].addEventListener("click",function(){selectPhone(idx);});allPhones[j].addEventListener("keydown",function(e){if(e.key==="Enter"||e.key===" "){e.preventDefault();selectPhone(idx);}});}}function selectPhone(index){activeIndex=index;const phones=marqueeTrack?marqueeTrack.children:[];for(let i=0;i<phones.length;i++){const idx=i % SCREEN_DATA.length;phones[i].classList.toggle("active",idx===activeIndex);}if(marqueeTrack){marqueeTrack.style.animationPlayState="paused";isPaused=true;}updateCaption(activeIndex);}function resumeMarquee(){if(marqueeTrack&&isPaused){marqueeTrack.style.animationPlayState="running";isPaused=false;}}function updateCaption(index){if(!captionBox||!captionTitle||!captionDesc)return;const data=SCREEN_DATA[index];captionBox.classList.add("fade");setTimeout(function(){captionTitle.textContent=data.title;captionDesc.textContent=data.desc;captionBox.classList.remove("fade");},320);}function initLogoSwap(){}function initStars(){const container=document.getElementById("stars");if(!container)return;const STAR_COUNT=24;const fragment=document.createDocumentFragment();for(let i=0;i<STAR_COUNT;i++){const star=document.createElement("div");star.className="star";star.style.left=Math.random()*100+"vw";star.style.width=star.style.height=3+Math.random()*5+"px";star.style.animationDuration=14+Math.random()*22+"s";star.style.animationDelay=-Math.random()*30+"s";star.style.opacity=0.15+Math.random()*0.25;fragment.appendChild(star);}container.appendChild(fragment);}function initHeader(){const header=document.querySelector(".site-header");if(!header)return;window.addEventListener("scroll",function(){if(window.scrollY>40){header.classList.add("scrolled");}else{header.classList.remove("scrolled");}},{passive:true});}function initNav(){const toggle=document.getElementById("navToggle");const links=document.getElementById("navLinks");if(!toggle||!links)return;toggle.addEventListener("click",function(){toggle.classList.toggle("open");links.classList.toggle("open");});links.querySelectorAll("a").forEach(function(link){link.addEventListener("click",function(){toggle.classList.remove("open");links.classList.remove("open");});});}function initFaq(){document.querySelectorAll(".faq-item.faq-q").forEach(function(q){q.addEventListener("click",function(){const item=q.closest(".faq-item");const wasOpen=item.classList.contains("open");const list=item.closest(".faq-list");if(list){list.querySelectorAll(".faq-item").forEach(function(other){other.classList.remove("open");});}if(!wasOpen){item.classList.add("open");}});});}function initForms(){const notifyForm=document.getElementById("notifyForm");const notifyEmail=document.getElementById("notifyEmail");const notifyNote=document.getElementById("notifyNote");if(notifyForm&&notifyNote){notifyForm.addEventListener("submit",function(e){e.preventDefault();const email=notifyEmail?notifyEmail.value.trim():"";if(!email)return;notifyNote.textContent="\u2728 Thank you!You'll be notified when GreatOhm launches.";notifyForm.reset();});}const contactForm=document.getElementById("contactForm");if(contactForm){contactForm.addEventListener("submit",function(e){e.preventDefault();alert("Thank you for your message!(Demo — connect this form to your email/backend.)");contactForm.reset();});}}document.addEventListener("DOMContentLoaded",function(){buildPhones();updateCaption(0);initLogoSwap();initStars();initHeader();initNav();initFaq();initForms();if(marqueeStage){marqueeStage.addEventListener("mouseleave",function(){resumeMarquee();});marqueeStage.addEventListener("touchend",function(){setTimeout(resumeMarquee,1500);});}});})();